CREATE TABLE IF NOT EXISTS parents (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,passwordHash TEXT NOT NULL,mfaEnabled INTEGER NOT NULL DEFAULT 0,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY,parentId TEXT NOT NULL,expiresAt TEXT NOT NULL,FOREIGN KEY(parentId) REFERENCES parents(id));
CREATE TABLE IF NOT EXISTS children (id TEXT PRIMARY KEY,parentId TEXT NOT NULL,name TEXT NOT NULL,ageBand TEXT,createdAt TEXT NOT NULL,FOREIGN KEY(parentId) REFERENCES parents(id));
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY,childId TEXT NOT NULL,platform TEXT NOT NULL,managementMode TEXT NOT NULL,status TEXT NOT NULL,lastSeenAt TEXT,grantedScopes TEXT NOT NULL,FOREIGN KEY(childId) REFERENCES children(id));
CREATE TABLE IF NOT EXISTS enrollTokens (id TEXT PRIMARY KEY,token TEXT UNIQUE NOT NULL,childId TEXT NOT NULL,createdByParentId TEXT NOT NULL,expiresAt TEXT NOT NULL,consumedAt TEXT,FOREIGN KEY(childId) REFERENCES children(id));
CREATE TABLE IF NOT EXISTS consentRecords (id TEXT PRIMARY KEY,deviceId TEXT NOT NULL,scope TEXT NOT NULL,grantedAt TEXT NOT NULL,revokedAt TEXT,FOREIGN KEY(deviceId) REFERENCES devices(id));
CREATE TABLE IF NOT EXISTS policies (deviceId TEXT PRIMARY KEY,policy TEXT NOT NULL,FOREIGN KEY(deviceId) REFERENCES devices(id));
CREATE TABLE IF NOT EXISTS auditLog (id TEXT PRIMARY KEY,parentId TEXT NOT NULL,action TEXT NOT NULL,detail TEXT,at TEXT NOT NULL,FOREIGN KEY(parentId) REFERENCES parents(id));
CREATE INDEX IF NOT EXISTS children_parent_idx ON children(parentId); CREATE INDEX IF NOT EXISTS devices_child_idx ON devices(childId); CREATE INDEX IF NOT EXISTS audit_parent_idx ON auditLog(parentId,at);
